      "id": "modal",
      "title": "Modal Dialog",
      "component": "import { useState } from \"react\";\nimport { Sheet } from \"../../velvet/index.js\";\nimport { px } from \"../px.js\";\nimport { IconCheck, IconChevronR } from \"../icons.jsx\";\nimport \"./Modal.css\";\n\nconst TEAM = [px(733872, 96, 96), px(614810, 96, 96), px(1239291, 96, 96)];\n\nexport const Modal = () => {\n  const [role, setRole] = useState(\"Editor\");\n  return (\n    <Sheet.Root>\n      <Sheet.Trigger className=\"Btn\">\n        Open invite <IconChevronR />\n      </Sheet.Trigger>\n      <Sheet.Portal>\n        <Sheet.View className=\"Modal-view\" side=\"center\" tracks={[\"top\", \"bottom\"]}>\n          <Sheet.Backdrop travelAnimation={{ opacity: ({ progress }) => progress * 0.5 }} />\n          <Sheet.Content\n            className=\"Modal-content\"\n            travelAnimation={{\n              opacity: ({ progress }) => Math.min(progress * 1.6, 1),\n              transform: ({ tween }) => `scale(${tween(0.94, 1)})`,\n            }}\n          >\n            <Sheet.BleedingBackground className=\"Modal-bg\" />\n            <div className=\"Modal-cover\">\n              <img src={px(4350210, 800, 400)} alt=\"The Atlas team around a laptop\" />\n              <div className=\"Modal-avatars\">\n                {TEAM.map((src) => (\n                  <img key={src} src={src} alt=\"\" />\n                ))}\n              </div>\n            </div>\n            <div className=\"Modal-body\">\n              <Sheet.Title className=\"Modal-title\">Join “Atlas Redesign”?</Sheet.Title>\n              <Sheet.Description className=\"Modal-desc\">\n                Ava Laurent invited you to collaborate with 11 others. Pick a role — you can\n                change it later.\n              </Sheet.Description>\n              <div className=\"Modal-roles\" role=\"group\" aria-label=\"Role\">\n                {[\"Viewer\", \"Editor\"].map((r) => (\n                  <button\n                    key={r}\n                    className=\"Modal-role\"\n                    data-active={role === r}\n                    aria-pressed={role === r}\n                    onClick={() => setRole(r)}\n                  >\n                    {r}\n                  </button>\n                ))}\n              </div>\n              <div className=\"Modal-actions\">\n                <Sheet.Trigger action=\"close\" className=\"Btn Btn--soft\">Not now</Sheet.Trigger>\n                <Sheet.Trigger action=\"close\" className=\"Btn Btn--primary\">\n                  <IconCheck size={15} /> Accept invite\n                </Sheet.Trigger>\n              </div>\n            </div>\n          </Sheet.Content>\n        </Sheet.View>\n      </Sheet.Portal>\n    </Sheet.Root>\n  );\n};",
      "styles": ".Modal-view {\n  height: var(--velvet-100lvh);\n}\n\n.Modal-content {\n  box-sizing: border-box;\n  width: calc(100vw - 40px);\n  max-width: 400px;\n  display: flex;\n  flex-direction: column;\n}\n\n.Modal-bg {\n  border-radius: 26px;\n  background: var(--cream-surface);\n  box-shadow: 0 30px 60px -24px rgba(60, 45, 30, 0.32), 0 0 0 0.5px rgba(60, 50, 38, 0.06);\n}\n\n.Modal-cover {\n  position: relative;\n  margin: 10px 10px 0;\n  border-radius: 18px;\n  overflow: hidden;\n}\n.Modal-cover > img {\n  display: block;\n  width: 100%;\n  height: 132px;\n  object-fit: cover;\n}\n.Modal-avatars {\n  position: absolute;\n  left: 14px;\n  bottom: -18px;\n  display: flex;\n}\n.Modal-avatars img {\n  width: 40px;\n  height: 40px;\n  border-radius: 999px;\n  object-fit: cover;\n  border: 3px solid var(--cream-surface);\n  margin-left: -10px;\n  box-shadow: 0 4px 12px -4px rgba(2, 6, 23, 0.3);\n}\n.Modal-avatars img:first-child {\n  margin-left: 0;\n}\n\n.Modal-body {\n  padding: 30px 22px 22px;\n}\n\n.Modal-title {\n  margin: 0 0 8px;\n  font-size: 20px;\n  font-weight: 700;\n  letter-spacing: -0.02em;\n  color: var(--ink);\n}\n\n.Modal-desc {\n  margin: 0 0 16px;\n  font-size: 14.5px;\n  line-height: 1.55;\n  color: var(--ink-soft);\n}\n\n.Modal-roles {\n  display: flex;\n  gap: 4px;\n  padding: 4px;\n  background: var(--cream-bg-2);\n  border-radius: 12px;\n  margin-bottom: 16px;\n}\n.Modal-role {\n  flex: 1;\n  appearance: none;\n  border: none;\n  background: none;\n  font: inherit;\n  font-size: 14px;\n  font-weight: 600;\n  color: var(--ink-soft);\n  padding: 8px 0;\n  border-radius: 9px;\n  cursor: pointer;\n  transition: background 160ms ease, color 160ms ease, box-shadow 160ms ease;\n}\n.Modal-role[data-active=\"true\"] {\n  background: var(--cream-surface);\n  color: var(--ink);\n  box-shadow: 0 1px 4px rgba(2, 6, 23, 0.1);\n}\n\n.Modal-actions {\n  display: flex;\n  gap: 10px;\n}\n.Modal-actions .Btn {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  gap: 6px;\n  padding: 11px 16px;\n}\n.Modal-actions .Btn--soft {\n  flex: 1;\n}\n.Modal-actions .Btn--primary {\n  flex: 1.6;\n}"
