    {
      "id": "persistent",
      "title": "Persistent Sheet",
      "component": "import { Sheet } from \"../../velvet/index.js\";\nimport { px } from \"../px.js\";\nimport {\n  IconChevronUp,\n  IconClose,\n  IconHeart,\n  IconMusic,\n  IconNext,\n  IconPlay,\n  IconPrev,\n  IconRepeat,\n  IconShuffle,\n} from \"../icons.jsx\";\nimport \"./PersistentSheet.css\";\n\nexport const PersistentSheet = () => (\n  <Sheet.Root defaultSnap={1}>\n    <Sheet.Trigger className=\"Btn\">\n      <IconMusic /> Show player\n    </Sheet.Trigger>\n    <Sheet.Portal>\n      <Sheet.View\n        className=\"Player-view\"\n        snapPoints=\"96px\"\n        dismissible={false}\n        modal={false}\n      >\n        <Sheet.Backdrop travelAnimation={{ opacity: ({ progress }) => Math.max(0, progress - 0.35) * 0.8 }} />\n        <Sheet.Content className=\"Player-content\">\n          <Sheet.BleedingBackground className=\"Player-bg\" />\n          <Sheet.Handle className=\"Player-handle\" />\n\n          <div className=\"Player-bar\">\n            <img className=\"Player-art\" src={px(1763075, 160, 160)} alt=\"Midnight Drive album art\" />\n            <div className=\"Player-meta\">\n              <Sheet.Title className=\"Player-title\">Midnight Drive</Sheet.Title>\n              <p className=\"Player-artist\">The Velvets</p>\n            </div>\n            <button className=\"Player-iconBtn\" aria-label=\"Play\">\n              <IconPlay size={17} />\n            </button>\n            <Sheet.Trigger action={{ type: \"step\", direction: \"up\" }} className=\"Player-iconBtn\" aria-label=\"Expand player\">\n              <IconChevronUp size={16} />\n            </Sheet.Trigger>\n            <Sheet.Trigger action=\"close\" className=\"Player-iconBtn\" aria-label=\"Close player\">\n              <IconClose size={15} />\n            </Sheet.Trigger>\n          </div>\n\n          <div className=\"Player-full\">\n            <img className=\"Player-bigArt\" src={px(1763075, 720, 720)} alt=\"\" />\n            <Sheet.Description className=\"Player-desc\">\n              A persistent sheet — it rests as a mini player, expands to full, and swiping down\n              can never dismiss it by accident.\n            </Sheet.Description>\n            <div className=\"Player-progress\">\n              <span>1:12</span>\n              <div className=\"Player-track\">\n                <i style={{ width: \"38%\" }} />\n              </div>\n              <span>3:42</span>\n            </div>\n            <div className=\"Player-controls\">\n              <button className=\"Player-ctl\" aria-label=\"Shuffle\">\n                <IconShuffle size={18} />\n              </button>\n              <button className=\"Player-ctl\" aria-label=\"Previous\">\n                <IconPrev size={20} />\n              </button>\n              <button className=\"Player-playMain\" aria-label=\"Play\">\n                <IconPlay size={22} />\n              </button>\n              <button className=\"Player-ctl\" aria-label=\"Next\">\n                <IconNext size={20} />\n              </button>\n              <button className=\"Player-ctl\" aria-label=\"Repeat\">\n                <IconRepeat size={18} />\n              </button>\n            </div>\n            <button className=\"Player-like\">\n              <IconHeart size={15} /> Add to favorites\n            </button>\n          </div>\n        </Sheet.Content>\n      </Sheet.View>\n    </Sheet.Portal>\n  </Sheet.Root>\n);",
      "styles": ".Player-view {\n  height: var(--velvet-100lvh);\n}\n.Player-content {\n  box-sizing: border-box;\n  width: 100%;\n  max-width: 480px;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n}\n.Player-bg {\n  border-radius: 22px 22px 0 0;\n  background: #101013;\n  box-shadow: 0 -16px 44px -18px rgba(0, 0, 0, 0.55);\n}\n.Player-handle {\n  margin: 7px auto 8px;\n  background: #3a3a40;\n}\n.Player-bar {\n  width: 100%;\n  box-sizing: border-box;\n  display: flex;\n  align-items: center;\n  gap: 12px;\n  padding: 2px 16px 10px;\n}\n.Player-art {\n  width: 46px;\n  height: 46px;\n  border-radius: 10px;\n  object-fit: cover;\n  flex: none;\n  box-shadow: 0 4px 14px -4px rgba(0, 0, 0, 0.5);\n}\n.Player-meta {\n  flex: 1;\n  min-width: 0;\n}\n.Player-title {\n  display: block;\n  margin: 0;\n  font-size: 15.5px;\n  font-weight: 600;\n  letter-spacing: -0.01em;\n  color: #fafafa;\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n.Player-artist {\n  margin: 2px 0 0;\n  font-size: 12.5px;\n  color: #8b8b93;\n}\n.Player-iconBtn {\n  flex: none;\n  width: 34px;\n  height: 34px;\n  display: grid;\n  place-items: center;\n  appearance: none;\n  border: none;\n  border-radius: 999px;\n  background: transparent;\n  color: #d4d4d8;\n  cursor: pointer;\n  transition: background 160ms ease, transform 160ms var(--ease);\n}\n.Player-iconBtn:hover {\n  background: #1e1e22;\n}\n.Player-iconBtn:active {\n  transform: scale(0.88);\n}\n.Player-full {\n  width: 100%;\n  box-sizing: border-box;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  padding: 14px 26px calc(22px + env(safe-area-inset-bottom));\n}\n.Player-bigArt {\n  width: min(64vw, 250px);\n  aspect-ratio: 1;\n  border-radius: 18px;\n  object-fit: cover;\n  box-shadow: 0 24px 60px -18px rgba(0, 0, 0, 0.6);\n}\n.Player-desc {\n  margin: 14px 0 0;\n  font-size: 13px;\n  line-height: 1.5;\n  text-align: center;\n  color: #8b8b93;\n  max-width: 340px;\n}\n.Player-progress {\n  width: 100%;\n  max-width: 340px;\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  margin-top: 16px;\n  font-size: 11.5px;\n  color: #8b8b93;\n  font-variant-numeric: tabular-nums;\n}\n.Player-track {\n  flex: 1;\n  height: 4px;\n  border-radius: 999px;\n  background: #2a2a30;\n  overflow: hidden;\n}\n.Player-track i {\n  display: block;\n  height: 100%;\n  border-radius: 999px;\n  background: #e879f9;\n}\n.Player-controls {\n  display: flex;\n  align-items: center;\n  gap: 18px;\n  margin-top: 18px;\n}\n.Player-ctl {\n  appearance: none;\n  border: none;\n  background: none;\n  color: #a1a1aa;\n  width: 40px;\n  height: 40px;\n  display: grid;\n  place-items: center;\n  border-radius: 999px;\n  cursor: pointer;\n  transition: color 160ms ease, background 160ms ease, transform 160ms var(--ease);\n}\n.Player-ctl:hover {\n  color: #fafafa;\n  background: #1e1e22;\n}\n.Player-ctl:active {\n  transform: scale(0.88);\n}\n.Player-playMain {\n  appearance: none;\n  border: none;\n  width: 62px;\n  height: 62px;\n  display: grid;\n  place-items: center;\n  border-radius: 999px;\n  background: #fafafa;\n  color: #101013;\n  cursor: pointer;\n  box-shadow: 0 10px 26px -8px rgba(255, 255, 255, 0.25);\n  transition: transform 160ms var(--ease);\n}\n.Player-playMain:active {\n  transform: scale(0.92);\n}\n.Player-like {\n  appearance: none;\n  border: 1px solid #2a2a30;\n  background: transparent;\n  color: #d4d4d8;\n  font: inherit;\n  font-size: 13px;\n  font-weight: 600;\n  display: inline-flex;\n  align-items: center;\n  gap: 7px;\n  margin-top: 18px;\n  padding: 9px 16px;\n  border-radius: 999px;\n  cursor: pointer;\n  transition: background 160ms ease, border-color 160ms ease;\n}\n.Player-like:hover {\n  background: #1a1a1f;\n}"
    }
